mapper.select:
SELECT COUNT(*) FROM v_to_v 
WHERE request_user_id = #{requestUserId} 
AND status NOT IN (2, 3)

SELECT v.id AS id, v.request_user_id AS requestUserId, u.name AS requestUserName, v.call_time AS callTime, v.call_position AS callPosition, v.call_longitude AS callLongitude, v.call_latitude AS callLatitude FROM v_to_v v LEFT JOIN user_info u ON v.request_user_id = u.id WHERE v.status = 0
AND v.call_longitude BETWEEN #{minLng} AND #{maxLng}
AND v.call_latitude BETWEEN #{minLat} AND #{maxLat}

SELECT v.id AS callId, CASE WHEN v.request_user_id = #{userId} THEN 0 ELSE 1 END AS role, v.call_range AS callRange, v.call_time AS callTime, v.status AS status, v.request_user_id AS callUserId, u1.name AS callUserName, v.response_user_id AS responseUserId, u2.name AS responseUserName, v.call_position AS callPosition, v.target_position AS targetPosition, v.target_longitude AS targetLongitude, v.target_latitude AS targetLatitude, v.call_longitude AS callLongitude, v.call_latitude AS callLatitude FROM v_to_v v LEFT JOIN user_info u1 ON v.request_user_id = u1.id LEFT JOIN user_info u2 ON v.response_user_id = u2.id WHERE (v.request_user_id = #{userId} OR v.response_user_id = #{userId})
AND (CASE WHEN v.request_user_id = #{userId} THEN 0 ELSE 1 END) = #{role}
AND v.status = #{status}
ORDER BY v.call_time DESC

SELECT COUNT(*) FROM emergency_call 
WHERE request_user_id = #{requestUserId} 
AND status NOT IN (2, 3)

SELECT e.id AS callId, e.type AS callType, e.call_time AS callTime, e.status AS status, e.response_admin_id AS responserId, a.name AS responserName, e.call_position AS callPosition, e.target_position AS targetPosition, e.target_longitude AS targetLongitude, e.target_latitude AS targetLatitude, e.call_longitude AS callLongitude, e.call_latitude AS callLatitude FROM emergency_call e LEFT JOIN admin_info a ON e.response_admin_id = a.id WHERE e.request_user_id = #{userId}
AND e.type = #{callType}
AND e.status = #{status}
ORDER BY e.call_time DESC
